  },
  "spec": {
    "pools": {
      "edge": {
        "name": "Edge cluster",
        "kind": "edge",
        "capacity": {
          "cpu": 8,
          "memory": 16
        },
        "properties": {
          "region": "eu-south"
        }
      },
      "fog": {
        "name": "Fog cluster",
        "kind": "fog",
        "capacity": {
          "cpu": 12,
          "memory": 24
        },
        "properties": {
          "region": "eu-west"
        }
      },
      "cloud": {
        "name": "Cloud region",
        "kind": "cloud",
        "capacity": {
          "cpu": 32,
          "memory": 64
        },
        "properties": {
          "region": "eu-central"
        }
      }
    },
    "defaults": {
      "cpu": 0.5,
      "memory": 1
    },
    "groups": {
