          "cpu": 1.25,
          "memory": 2
        }
      }
    },
    "networkMode": "symmetric",
    "network": [
      {
        "from": {
          "resource": "placement",
          "id": "edge"
        },
        "to": {
          "resource": "placement",
          "id": "edge"
        },
        "latency": 0
      },
      {
        "from": {
          "resource": "placement",
          "id": "fog"
        },
        "to": {
          "resource": "placement",
          "id": "fog"
        },
        "latency": 0
      },
      {
        "from": {
          "resource": "placement",
          "id": "cloud"
        },
        "to": {
          "resource": "placement",
          "id": "cloud"
        },
        "latency": 0
      },
      {
        "from": {
          "resource": "placement",
          "id": "edge"
        },
        "to": {
          "resource": "placement",
          "id": "fog"
        },
        "latency": 8
