          {
            "pool": {
              "resource": "placement",
              "id": "nowhere"
            },
            "latency": 6
          },
          {
            "pool": {
              "resource": "placement",
              "id": "cloud"
            },
            "latency": 18
          }
        ]
      }
    },
    "transitions": {
      "client-to-auth": {
        "from": {
          "resource": "placement",
          "id": "client-request"
        },
        "to": {
          "resource": "application",
          "id": "authenticate"
        },
        "feature": {
          "resource": "application",
          "id": "latency"
        },
        "maximum": 30,
        "enforcement": "hard"
      },
      "auth-to-enrich": {
        "from": {
          "resource": "application",
          "id": "authenticate"
