        "to": {
          "resource": "application",
          "id": "publish"
        },
        "feature": {
          "resource": "application",
          "id": "latency"
        },
        "maximum": 20,
        "enforcement": "hard"
      }
    },
    "capacityRules": [
      {
        "resources": [
          "cpu",
          "gpu"
        ],
        "scope": "selectedCandidate"
      }
    ],
    "globalLatency": {
      "feature": {
        "resource": "application",
        "id": "latency"
      },
      "includeExecution": true,
      "exclusive": "routing",
      "parallel": "max"
    }
  }
}

